def solve(grid):
    h = len(grid)
    w = len(grid[0]) if h else 0

    out = [[7 if grid[r][c] == 7 else 0 for c in range(w)] for r in range(h)]
    seen = [[False] * w for _ in range(h)]

    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    for sr in range(h):
        for sc in range(w):
            if grid[sr][sc] == 7 or seen[sr][sc]:
                continue

            # Find one connected component of non-7 cells.
            stack = [(sr, sc)]
            seen[sr][sc] = True
            cells = []
            count8 = 0

            while stack:
                r, c = stack.pop()
                cells.append((r, c))
                if grid[r][c] == 8:
                    count8 += 1
                for dr, dc in dirs:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and not seen[nr][nc] and grid[nr][nc] != 7:
                        seen[nr][nc] = True
                        stack.append((nr, nc))

            # Group component cells by row.
            row_cells = {}
            for r, c in cells:
                row_cells.setdefault(r, []).append(c)
            for r in row_cells:
                row_cells[r].sort()

            remaining = count8
            prev_filled_cols = None

            # Fill from bottom to top.
            for r in sorted(row_cells.keys(), reverse=True):
                cols = row_cells[r]
                cap = len(cols)
                if remaining <= 0:
                    break

                if remaining >= cap:
                    for c in cols:
                        out[r][c] = 8
                    remaining -= cap
                    prev_filled_cols = cols[:]
                else:
                    # Choose a partial set in this row.
                    if prev_filled_cols is None:
                        center = (cols[0] + cols[-1]) / 2.0
                        ranked = sorted(cols, key=lambda c: (abs(c - center), c))
                    else:
                        center = (cols[0] + cols[-1]) / 2.0
                        ranked = sorted(
                            cols,
                            key=lambda c: (
                                min(abs(c - pc) for pc in prev_filled_cols),
                                abs(c - center),
                                c,
                            ),
                        )
                    chosen = set(ranked[:remaining])
                    for c in cols:
                        if c in chosen:
                            out[r][c] = 8
                    remaining = 0
                    prev_filled_cols = sorted(chosen)

    return out

